export enum Membership_Status {
  StatusUnknown = 0,
  /**
   * StatusPending - please wait a bit more, we are still processing your request
   * the payment is confirmed, but we need more time to do some side-effects:
   * - increase limits
   * - send emails
   * - allocate names
   */
  StatusPending = 1,
  /** StatusActive - the membership is active, ready to use! */
  StatusActive = 2,
  /**
   * StatusPendingRequiresFinalization - in some cases we need to finalize the process:
   * - if user has bought membership directly without first calling
   * the BuySubscription method
   * in this case please call Finalize to finish the process
   */
  StatusPendingRequiresFinalization = 3,
  UNRECOGNIZED = -1,
}

export function membership_StatusFromJSON(object: any): Membership_Status {
  switch (object) {
    case 0:
    case "StatusUnknown":
      return Membership_Status.StatusUnknown;
    case 1:
    case "StatusPending":
      return Membership_Status.StatusPending;
    case 2:
    case "StatusActive":
      return Membership_Status.StatusActive;
    case 3:
    case "StatusPendingRequiresFinalization":
      return Membership_Status.StatusPendingRequiresFinalization;
    case -1:
    case "UNRECOGNIZED":
    default:
      return Membership_Status.UNRECOGNIZED;
  }
}

export function membership_StatusToJSON(object: Membership_Status): string {
  switch (object) {
    case Membership_Status.StatusUnknown:
      return "StatusUnknown";
    case Membership_Status.StatusPending:
      return "StatusPending";
    case Membership_Status.StatusActive:
      return "StatusActive";
    case Membership_Status.StatusPendingRequiresFinalization:
      return "StatusPendingRequiresFinalization";
    case Membership_Status.UNRECOGNIZED:
    default:
      return "UNRECOGNIZED";
  }
}

